import '../../core/errors/app_error.dart';
import '../../core/widgets/common.dart';
import '../academics/domain/drive.dart';
import '../downloads/data/downloads_controller.dart';
import '../downloads/domain/download_record.dart';
import '../home/data/recent_controller.dart';
import 'offline_pdf.dart';
import 'native_preview.dart';
import 'reader_chrome.dart';
import '../../core/utils/links.dart';
import '../../core/utils/media_upload.dart';

/// Document viewer. Native chrome, Back top-left, NO "Open original".
class ViewerScreen extends ConsumerStatefulWidget {
  const ViewerScreen({super.key, required this.file});
  final FileRef? file;
  @override
  ConsumerState<ViewerScreen> createState() => _ViewerScreenState();
}

class _ViewerScreenState extends ConsumerState<ViewerScreen> {
  bool _preferOnline = false;
  final _tools = ReaderTools();

  @override
  void initState() {
    super.initState();
    final f = widget.file;
    if (f != null) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        ref.read(recentProvider.notifier).touch(f);
      });
    }
  }

  Future<void> _save(FileRef f) async {
    try {
      await ref.read(downloadsProvider.notifier).save(f);
      if (mounted) {
        showHSnack(context, 'Saved offline \u2014 find it in Downloads');
      }
    } on FriendlyException catch (e) {
      if (mounted) showHSnack(context, e.message, error: true);
    } catch (_) {
      if (mounted) {
        showHSnack(
          context,
          'Could not save this file. Please retry.',
          error: true,
        );
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    final f = widget.file;
    if (f == null) {
      return Scaffold(
        appBar: const HTopBar(title: 'Document'),
        body: EmptyState(
          icon: Icons.description_outlined,
          title: 'Nothing to show',
          action: HButton(
            label: 'Go home',
            onPressed: () => context.go('/home'),
          ),
        ),
      );
    }
    final rec = ref.watch(downloadForUrlProvider(f.url));
    final ready = rec?.isReady == true && !kIsWeb;
    final showOffline = ready && !_preferOnline;
    final downloading = rec?.status == DownloadStatus.downloading;
    return ReaderScaffold(
      title: f.title,
      onShare: ready ? () => MediaUpload.shareDocument(rec!.localPath!, f.title, 'application/pdf') : null,
      actions: [
        if (!kIsWeb) ReaderAction(
          ready ? 'Saved offline' : downloading ? 'Downloading…' : 'Save offline',
          ready ? Icons.offline_pin_rounded : Icons.download_rounded,
          () { if (!ready && !downloading) _save(f); }),
        if (downloading) ReaderAction('Pause download', Icons.pause_rounded,
          () => ref.read(downloadsProvider.notifier).cancel(DriveLinks.offlineKey(f.url))),
        if (ready) ...[
          ReaderAction('Save As', Icons.save_alt_rounded,
            () => MediaUpload.exportDocument(rec!.localPath!, f.title, 'application/octet-stream')),
          ReaderAction(showOffline ? 'Show online preview' : 'Read offline', Icons.cloud_outlined,
            () => setState(() => _preferOnline = !_preferOnline)),
        ],
        ReaderAction('Pages view', Icons.grid_view_rounded, () => _tools.run('pages', context)),
        ReaderAction('Search PDF', Icons.search_rounded, () => _tools.run('search', context)),
        ReaderAction('Zoom in', Icons.zoom_in_rounded, () => _tools.run('in', context)),
        ReaderAction('Zoom out', Icons.zoom_out_rounded, () => _tools.run('out', context)),
        ReaderAction('Open in browser', Icons.open_in_new_rounded, () => openLink(context, f.url)),
      ],
      banner: downloading ? LinearProgressIndicator(value: rec!.progress > 0 ? rec.progress : null, minHeight: 2) : null,
      child: showOffline
          ? OfflinePdf(path: rec!.localPath!, tools: _tools)
          : NativePreview(key: ValueKey(f.url), url: f.url, tools: _tools),
    );
  }
}

